    printf("sizeof(struct resource) = %zu\n", sizeof(struct resource));
    printf("sizeof(struct question) = %zu\n", sizeof(struct question));

    bool success = message_parse(&m, dataCopy, size);

    if (!success) {
        printf("message_parse returned false\n");
        printf("m->_len = %lu\n", m._len);
        free(dataCopy);
        free(data);
        return 0;
